{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "To ensure that all children receive a high-quality education and to close the achievement gap between children meeting challenging State academic standards and those not meeting them, each local educational agency plan must describe the specified plan provisions."
    },
    {
      "quote_ref": "F001",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe how the local educational agency will monitor students' progress in meeting the challenging State academic standards through the methods specified in subparagraphs (A) through (D)."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F000", "F001"],
      "kind": "requirement",
      "meaning": "As part of describing how it will monitor students' progress in meeting challenging State academic standards, the local educational agency plan must describe how the agency will develop and implement a well-rounded program of instruction to meet the academic needs of all students."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F000", "F001"],
      "kind": "requirement",
      "meaning": "As part of describing how it will monitor students' progress in meeting challenging State academic standards, the local educational agency plan must describe how the agency will identify students who may be at risk for academic failure."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F000", "F001"],
      "kind": "requirement",
      "meaning": "As part of describing how it will monitor students' progress in meeting challenging State academic standards, the local educational agency plan must describe how the agency will provide additional educational assistance to individual students whom the local educational agency or school determines need help in meeting challenging State academic standards."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F000", "F001"],
      "kind": "requirement",
      "meaning": "As part of describing how it will monitor students' progress in meeting challenging State academic standards, the local educational agency plan must describe how the agency will identify and implement instructional and other strategies intended to strengthen academic programs and improve school conditions for student learning."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe how the local educational agency will identify and address, as required under State plans described in section 6311(g)(1)(B), any disparities that result in low-income students and minority students being taught at higher rates than other students by ineffective, inexperienced, or out-of-field teachers."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe how the local educational agency will carry out its responsibilities under paragraphs (1) and (2) of section 6311(d)."
    },
    {
      "quote_ref": "F009",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe the poverty criteria that will be used to select school attendance areas under section 6313."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe, in general, the nature of the programs to be conducted by the agency's schools under sections 6314 and 6315 and, where appropriate, educational services outside such schools for children living in local institutions for neglected or delinquent children, and for neglected and delinquent children in community day school programs."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe the services the local educational agency will provide homeless children and youths, including services provided with funds reserved under section 6313(c)(3)(A), to support their enrollment, attendance, and success, in coordination with services provided under the McKinney-Vento Homeless Assistance Act."
    },
    {
      "quote_ref": "F012",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe the strategy the local educational agency will use to implement effective parent and family engagement under section 6318."
    },
    {
      "quote_ref": "F013",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "If applicable, each local educational agency plan must describe how the local educational agency will support, coordinate, and integrate services provided under this part with early childhood education programs at the agency or individual school level, including plans for the transition of participants in such programs to local elementary school programs."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe how teachers and school leaders, in consultation with parents, administrators, paraprofessionals, and specialized instructional support personnel, in schools operating a targeted assistance school program under section 6315, will identify the eligible children most in need of services under this part."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe how the local educational agency will implement strategies to facilitate effective transitions for students from middle grades to high school and from high school to postsecondary education, including through specified approaches if applicable."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F000", "F015"],
      "kind": "permission",
      "meaning": "In describing strategies to facilitate effective student transitions from middle grades to high school and from high school to postsecondary education, the plan may describe doing so, if applicable, through coordination with institutions of higher education, employers, and other local partners."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F000", "F015"],
      "kind": "permission",
      "meaning": "In describing strategies to facilitate effective student transitions from middle grades to high school and from high school to postsecondary education, the plan may describe doing so, if applicable, through increased student access to early college high school or dual or concurrent enrollment opportunities, or career counseling to identify student interests and skills."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe how the local educational agency will support efforts to reduce the overuse of discipline practices that remove students from the classroom, which may include identifying and supporting schools with high rates of discipline, disaggregated by each student subgroup defined in section 6311(c)(2)."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "If determined appropriate by the local educational agency, its plan must describe how the agency will support programs that coordinate and integrate academic and career and technical education content, as well as work-based learning opportunities."
    },
    {
      "quote_ref": "F021",
      "scope_refs": ["F000", "F020"],
      "kind": "requirement",
      "meaning": "Where the local educational agency determines it appropriate, the plan must describe how it will support programs coordinating and integrating academic and career and technical education content through coordinated instructional strategies, which may incorporate experiential learning opportunities and promote skills attainment important to in-demand occupations or industries in the State."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F000", "F020"],
      "kind": "requirement",
      "meaning": "Where the local educational agency determines it appropriate, the plan must describe how it will support programs coordinating and integrating work-based learning opportunities that provide students in-depth interaction with industry professionals and, if appropriate, academic credit."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan must describe any other information on how the agency proposes to use funds to meet the purposes of this part that the local educational agency determines appropriate to provide, which may include assistance to schools under subparagraphs (A) and (B)."
    },
    {
      "quote_ref": "F025",
      "scope_refs": ["F000", "F024"],
      "kind": "permission",
      "meaning": "The optional information described in the plan on proposed fund usage that the local educational agency determines appropriate may include how the local educational agency will assist schools in identifying and serving gifted and talented students."
    },
    {
      "quote_ref": "F026",
      "scope_refs": ["F000", "F024"],
      "kind": "permission",
      "meaning": "The optional information described in the plan on proposed fund usage that the local educational agency determines appropriate may include how the local educational agency will assist schools in developing effective school library programs to provide students an opportunity to develop digital literacy skills and improve academic achievement."
    }
  ]
}
